This sadly did nothing. I did ofc edit the values etc.
The thing I want to do is that, basically, any skill can be used with its MP cost. If the user's MP is below the cost, it will instead drain that amount in HP.
I am not good with code, I am trying to figure it out, but all the descriptions online seem to me to require I have good knowledge of javascript. Which I do not have.

I'd like to offer a solution for non VS users as well - make changes as needed:
JavaScript:
(($) => {
    // Alias skill cost to allow overage to drain hp if mp is 0
    const alias = $.paySkillCost;
    $.paySkillCost = function(skill) {
        const cost = this.skillMpCost(skill);
        if (cost > this._mp) {
            this._hp -= cost - this._mp;
            this._mp = 0;
            this._tp -= this.skillTpCost(skill);
        } else {
            alias.call(this, skill);
        }
    }
    // rewrite condition to allow payment for skill based on hp and mp
    $.canPaySkillCost = function(skill) {
        const mpCost    = this.skillMpCost(skill);
        const condition = this._tp >= this.skillTpCost(skill) &&
            (this._mp >= mpCost || this._hp + this._mp >= mpCost);
        return condition;
    }
})(Game_BattlerBase.prototype);
